import React, { useEffect, useMemo, useState } from "react";

export default function BaristaBillPage() {
  const [billData, setBillData] = useState({});

  useEffect(() => {
    const data = JSON.parse(localStorage.getItem("billData")) || {};
    setBillData(data);
  }, []);

  const rows = useMemo(() => {
    return Object.keys(billData).map((name) => {
      const count = billData[name]?.count ?? 0;
      const price = billData[name]?.price ?? 0;
      const total = count * price;
      return { name, count, price, total };
    });
  }, [billData]);

  const totalAmount = useMemo(() => rows.reduce((sum, r) => sum + r.total, 0), [rows]);

  function payNow(e) {
    e.preventDefault();
    alert("Payment processing... (this is just a placeholder)");
  }

  return (
    <>
      <style>{`
        body {
          font-family: Arial, sans-serif;
          margin: 20px;
        }

        header {
          text-align: center;
          padding: 10px;
          background-color: #f0f0f0;
          border-radius: 10px;
        }

        .bill-container {
          border: 2px solid #ec2020;
          border-radius: 10px;
          padding: 20px;
          background-color: #f9f9f9;
          max-width: 600px;
          margin: 0 auto;
        }

        h3, h4 {
          text-align: center;
        }

        .bill-items {
          list-style: none;
          padding: 0;
        }

        .bill-items li {
          padding: 10px;
          border-bottom: 1px solid #ddd;
          display: flex;
          justify-content: space-between;
        }

        .pay-now {
          display: block;
          background-color: #4CAF50;
          color: white;
          text-align: center;
          padding: 10px;
          border: none;
          border-radius: 5px;
          margin-top: 20px;
          cursor: pointer;
          text-decoration: none;
        }

        .pay-now:hover {
          background-color: #45a049;
        }
      `}</style>

      <header>
        <h1>Your Bill</h1>
      </header>
      <div className="bill-container">
        <h3>Your Bill:</h3>
        <ul className="bill-items" id="bill-items">
          {rows.map((r) => (
            <li key={r.name}>{`${r.name} x ${r.count} - ₹${r.total.toFixed(2)}`}</li>
          ))}
        </ul>
        <h4 id="total">{`Total: ₹${totalAmount.toFixed(2)}`}</h4>
        <a href="#" className="pay-now" onClick={payNow}>
          Pay Now
        </a>
      </div>
    </>
  );
}
